      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1RC_1LC1RA_1LD1RA_0RC0LD
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 3; SWinL 3]).
    vm_compute; reflexivity.
