  rewrite (gsi_1RB1RC_1LC1RA_1RA0LD_0RB1LD p j q0 E).
  exact (srun_sound tm false true chi_1RB1RC_1LC1RA_1RA0LD_0RB1LD A0_1RB1RC_1LC1RA_1RA0LD_0RB1LD A1_1RB1RC_1LC1RA_1RA0LD_0RB1LD 4 16
           run_int_1RB1RC_1LC1RA_1RA0LD_0RB1LD (Jp q0 ++ [S1;S0;S1;S0]) [] j
