  unfold Cc_1RB1RC_1LC1RA_1RA0LD_0RB1LD, cden, B0_1RB1RC_1LC1RA_1RA0LD_0RB1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
