Lemma lbl_1RB1RC_1LC1RA_1RA0LD_0RB1LD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RC_1LC1RA_1RA0LD_0RB1LD : forall p j, cview p = (S j, None) ->
