Lemma fireo_1RB1RC_1LC1RA_1RA0LD_0RB1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RC_1LC1RA_1RA0LD_0RB1LD = Some t ->
