Lemma firex_1RB1RC_1LC1RA_1RA0LD_0RB1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1RC_1LC1RA_1RA0LD_0RB1LD = Some t ->
  forall p j, cview p = (S j, None) ->
