  apply (fire_via_fill tm Cc Cin lapin_1RB1RC_1LC1RA_1RA0LD_0RB1LD t p (pow2 j)).
  - exists (4 * j + 16), (cden [] [] j BB1_1RB1RC_1LC1RA_1RA0LD_0RB1LD). split;
      [| exact (gbo_1RB1RC_1LC1RA_1RA0LD_0RB1LD j)].
