Lemma gsi_1RB1RC_1RC0LC_1LD1RA_0RC0LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_000_001_1 q0 ++ [S0]) [] j A0_1RB1RC_1RC0LC_1LD1RA_0RC0LD.
