Lemma fire_1RB1RC_1RC1RB_1LD1RA_0RB0LD : forall t, ~ In t pins_1RB1RC_1RC1RB_1LD1RA_0RB0LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
