Proof. exact lapi_1RB1RC_1RC1RB_1LD1RA_0RC0LD. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1RC_1RC1RB_1LD1RA_0RC0LD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin2 lapin2_1RB1RC_1RC1RB_1LD1RA_0RC0LD p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (6 * j + 19), (cden [] [] j BB1_1RB1RC_1RC1RB_1LD1RA_0RC0LD).
      split; [lia|]. split; [| exact (gbo_1RB1RC_1RC1RB_1LD1RA_0RC0LD j)].
      rewrite (gso_1RB1RC_1RC1RB_1LD1RA_0RC0LD p j E).
      exact (srun_sound tm true true chb_1RB1RC_1RC1RB_1LD1RA_0RC0LD B0_1RB1RC_1RC1RB_1LD1RA_0RC0LD BB1_1RB1RC_1RC1RB_1LD1RA_0RC0LD 6 19
               run_boot_1RB1RC_1RC1RB_1LD1RA_0RC0LD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1RC_1RC1RB_1LD1RA_0RC0LD p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (6 * j + 10), (cden [] [] j BM1_1RB1RC_1RC1RB_1LD1RA_0RC0LD).
      split; [| exact (gbo2_1RB1RC_1RC1RB_1LD1RA_0RC0LD j)].
      rewrite (gxi_1RB1RC_1RC1RB_1LD1RA_0RC0LD j).
      exact (srun_sound tm true true chm_1RB1RC_1RC1RB_1LD1RA_0RC0LD BM0_1RB1RC_1RC1RB_1LD1RA_0RC0LD BM1_1RB1RC_1RC1RB_1LD1RA_0RC0LD 6 10
               run_shift_1RB1RC_1RC1RB_1LD1RA_0RC0LD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB2.
