             run_exit_1RB1RC_1RC1RB_1LD1RA_0RC0LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1RC_1RC1RB_1LD1RA_0RC0LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RC_1RC1RB_1LD1RA_0RC0LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1RC_1RC1RB_1LD1RA_0RC0LD p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1RC_1RC1RB_1LD1RA_0RC0LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 23.
  assert (H : match csteps tm 23 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 23 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RC_1RC1RB_1LD1RA_0RC0LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RC_1RC1RB_1LD1RA_0RC0LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RC_1RC1RB_1LD1RA_0RC0LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RC_1RC1RB_1LD1RA_0RC0LD p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma firex_1RB1RC_1RC1RB_1LD1RA_0RC0LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1RC_1RC1RB_1LD1RA_0RC0LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin (pow2 j))).
  { exists (6 * j + 19), (cden [] [] j BB1_1RB1RC_1RC1RB_1LD1RA_0RC0LD).
    split; [lia|]. split; [| exact (gbo_1RB1RC_1RC1RB_1LD1RA_0RC0LD j)].
    rewrite (gso_1RB1RC_1RC1RB_1LD1RA_0RC0LD p j E).
    exact (srun_sound tm true true chb_1RB1RC_1RC1RB_1LD1RA_0RC0LD B0_1RB1RC_1RC1RB_1LD1RA_0RC0LD BB1_1RB1RC_1RC1RB_1LD1RA_0RC0LD 6 19
             run_boot_1RB1RC_1RC1RB_1LD1RA_0RC0LD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1RC_1RC1RB_1LD1RA_0RC0LD p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (6 * j + 10), (cden [] [] j BM1_1RB1RC_1RC1RB_1LD1RA_0RC0LD).
    split; [| exact (gbo2_1RB1RC_1RC1RB_1LD1RA_0RC0LD j)].
    rewrite (gxi_1RB1RC_1RC1RB_1LD1RA_0RC0LD j).
    exact (srun_sound tm true true chm_1RB1RC_1RC1RB_1LD1RA_0RC0LD BM0_1RB1RC_1RC1RB_1LD1RA_0RC0LD BM1_1RB1RC_1RC1RB_1LD1RA_0RC0LD 6 10
             run_shift_1RB1RC_1RC1RB_1LD1RA_0RC0LD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  destruct HB2 as (nB & cB & _ & HcB & HlB).
  apply (fire_via_fill tm Cc Cin2 lapin2_1RB1RC_1RC1RB_1LD1RA_0RC0LD t p (pow2 j));
    [exists nB, cB; exact (conj HcB HlB)|].
  apply (fire_lift_of_csteps tm (fun _ : positive => Cin2 (fill (pow2 j))) xH).
  apply (fire_of_run_instr tm (fun _ : positive => Cin2 (fill (pow2 j)))
                    true true l BE0_1RB1RC_1RC1RB_1LD1RA_0RC0LD xH j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gxi2_1RB1RC_1RC1RB_1LD1RA_0RC0LD j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RC_1RC1RB_1LD1RA_0RC0LD : forall t, ~ In t pins_1RB1RC_1RC1RB_1LD1RA_0RC0LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1RC_1RC1RB_1LD1RA_0RC0LD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RC_1RC1RB_1LD1RA_0RC0LD [SWin 3; SWinR 5] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RC_1RC1RB_1LD1RA_0RC0LD [SWin 3; SWinR 7; SCycL 3 0; SWin 1] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RC_1RC1RB_1LD1RA_0RC0LD [SWin 3; SWinR 6] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RC_1RC1RB_1LD1RA_0RC0LD (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1RC_1RC1RB_1LD1RA_0RC0LD [SWinR 2; SCycL 3 0; SWin 5] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RC_1RC1RB_1LD1RA_0RC0LD [] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RC_1RC1RB_1LD1RA_0RC0LD [SWin 3; SWinR 4] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RC_1RC1RB_1LD1RA_0RC0LD [SWin 3; SWinR 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RC_1RC1RB_1LD1RA_0RC0LD [SWin 1] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtrm_1RB1RC_1RC1RB_1LD1RA_0RC0LD : NeverQuasiHaltsTr tmm_1RB1RC_1RC1RB_1LD1RA_0RC0LD.
Proof.
  apply (glue_neverqhtr tmm_1RB1RC_1RC1RB_1LD1RA_0RC0LD pins_1RB1RC_1RC1RB_1LD1RA_0RC0LD Cc 1).
