(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1RD_0LB0LC_1RA1LC_0LC0RA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z0_1RB1RD_0LB0LC_1RA1LC_0LC0RA /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_1RB1RD_0LB0LC_1RA1LC_0LC0RA = Cc (Pos.succ p).
