Lemma fireo_1RB1RD_0LB0LC_1RA1LC_1RB0RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RD_0LB0LC_1RA1LC_1RB0RA = Some t ->
