Definition Cc_1RB1RD_0LB1LC_0RA0LB_1LB1RA (p : positive) : cconf := (StC, (Ip p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB1RD_0LB1LC_0RA0LB_1LB1RA.

(** ** The certificate *)

Definition A0_1RB1RD_0LB1LC_0RA0LB_1LB1RA : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition A1_1RB1RD_0LB1LC_0RA0LB_1LB1RA : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chi_1RB1RD_0LB1LC_0RA0LB_1LB1RA : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_int_1RB1RD_0LB1LC_0RA0LB_1LB1RA : srun tm false true chi_1RB1RD_0LB1LC_0RA0LB_1LB1RA A0_1RB1RD_0LB1LC_0RA0LB_1LB1RA = Some (A1_1RB1RD_0LB1LC_0RA0LB_1LB1RA, 4, 4).
