    apply (lap_of_run tm Cc true true cho_1RB1RD_0LB1LC_0RA1LC_1RA0LC B0_1RB1RD_0LB1LC_0RA1LC_1RA0LC B1_1RB1RD_0LB1LC_0RA1LC_1RA0LC 4 8 p j' [] []).
