(** 1RB1RD_0LC0LC_0RD1LB_1LC1RA -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB1RD_0LC0LC_0RD1LB_1LC1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DR StD
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S0 DL StC
  | StC, S0 => mk S0 DR StD | StC, S1 => mk S1 DL StB
  | StD, S0 => mk S1 DL StC | StD, S1 => mk S1 DR StA end.

(** Its mirror 1LB1LD_0RC0RC_0LD1RB_1RC1LA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1RD_0LC0LC_0RD1LB_1LC1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DL StD
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S0 DR StC
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S1 DR StB
  | StD, S0 => mk S1 DR StC | StD, S1 => mk S1 DL StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1RD_0LC0LC_0RD1LB_1LC1RA : list Instr := [].
Definition tmw_1RB1RD_0LC0LC_0RD1LB_1LC1RA : TM := tm_wrap_trs tmm_1RB1RD_0LC0LC_0RD1LB_1LC1RA pins_1RB1RD_0LC0LC_0RD1LB_1LC1RA.
Local Notation tm := tmw_1RB1RD_0LC0LC_0RD1LB_1LC1RA.

Lemma mirror_ok_1RB1RD_0LC0LC_0RD1LB_1LC1RA : mirror_tm tm_1RB1RD_0LC0LC_0RD1LB_1LC1RA = tmm_1RB1RD_0LC0LC_0RD1LB_1LC1RA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB1RD_0LC0LC_0RD1LB_1LC1RA (p : positive) : cconf := (StD, (Ip p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB1RD_0LC0LC_0RD1LB_1LC1RA.

(** ** The certificate *)

Definition A0_1RB1RD_0LC0LC_0RD1LB_1LC1RA : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition A1_1RB1RD_0LC0LC_0RD1LB_1LC1RA : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chi_1RB1RD_0LC0LC_0RD1LB_1LC1RA : list lstep := [SWinR 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_int_1RB1RD_0LC0LC_0RD1LB_1LC1RA : srun tm false true chi_1RB1RD_0LC0LC_0RD1LB_1LC1RA A0_1RB1RD_0LC0LC_0RD1LB_1LC1RA = Some (A1_1RB1RD_0LC0LC_0RD1LB_1LC1RA, 4, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1RD_0LC0LC_0RD1LB_1LC1RA : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1RD_0LC0LC_0RD1LB_1LC1RA : sconf := mkC StD (mkS [] [S1;S0] 1 1 [S1;S0]) S0 (mkS [S0] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StD *)
Definition Cin_1RB1RD_0LC0LC_0RD1LB_1LC1RA (v : positive) : cconf := (StD, (Ip v ++ [S1], S0, [])).
Local Notation Cin := Cin_1RB1RD_0LC0LC_0RD1LB_1LC1RA.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1RD_0LC0LC_0RD1LB_1LC1RA : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB1RD_0LC0LC_0RD1LB_1LC1RA : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chn_1RB1RD_0LC0LC_0RD1LB_1LC1RA : list lstep := [SWinR 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_inner_1RB1RD_0LC0LC_0RD1LB_1LC1RA : srun tm false true chn_1RB1RD_0LC0LC_0RD1LB_1LC1RA AI0_1RB1RD_0LC0LC_0RD1LB_1LC1RA = Some (AI1_1RB1RD_0LC0LC_0RD1LB_1LC1RA, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1RD_0LC0LC_0RD1LB_1LC1RA : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chb_1RB1RD_0LC0LC_0RD1LB_1LC1RA : list lstep := [SWinR 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_boot_1RB1RD_0LC0LC_0RD1LB_1LC1RA : srun tm true true chb_1RB1RD_0LC0LC_0RD1LB_1LC1RA B0_1RB1RD_0LC0LC_0RD1LB_1LC1RA = Some (BB1_1RB1RD_0LC0LC_0RD1LB_1LC1RA, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1RD_0LC0LC_0RD1LB_1LC1RA : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1RD_0LC0LC_0RD1LB_1LC1RA : list lstep := [SWinR 2; SCycL 2 0; SWin 2; SWinL 6; SCycR 2; SWin 2; SRotL 2; SFoldL 1].

Lemma run_exit_1RB1RD_0LC0LC_0RD1LB_1LC1RA : srun tm true true che_1RB1RD_0LC0LC_0RD1LB_1LC1RA BE0_1RB1RD_0LC0LC_0RD1LB_1LC1RA = Some (B1_1RB1RD_0LC0LC_0RD1LB_1LC1RA, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ip q0 ++ [S0]) [] j A0_1RB1RD_0LC0LC_0RD1LB_1LC1RA.
Proof.
  intros p j q0 E. destruct (ILCounter.cview_some_I p j q0 E) as (H1 & _).
  unfold Cc_1RB1RD_0LC0LC_0RD1LB_1LC1RA, cden, A0_1RB1RD_0LC0LC_0RD1LB_1LC1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ip q0 ++ [S0]) [] j A1_1RB1RD_0LC0LC_0RD1LB_1LC1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (ILCounter.cview_some_I p j q0 E) as (_ & H2).
  unfold Cc_1RB1RD_0LC0LC_0RD1LB_1LC1RA, cden, A1_1RB1RD_0LC0LC_0RD1LB_1LC1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (4 * j + 8), (cden (Ip q0 ++ [S0]) [] j A1_1RB1RD_0LC0LC_0RD1LB_1LC1RA).
  split; [lia|]. split; [| exact (gei_1RB1RD_0LC0LC_0RD1LB_1LC1RA p j q0 E)].
  rewrite (gsi_1RB1RD_0LC0LC_0RD1LB_1LC1RA p j q0 E).
  exact (srun_sound tm false true chi_1RB1RD_0LC0LC_0RD1LB_1LC1RA A0_1RB1RD_0LC0LC_0RD1LB_1LC1RA A1_1RB1RD_0LC0LC_0RD1LB_1LC1RA 4 8
           run_int_1RB1RD_0LC0LC_0RD1LB_1LC1RA (Ip q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RD_0LC0LC_0RD1LB_1LC1RA.
Proof.
  intros p j E. destruct (ILCounter.cview_none_I p j E) as (H1 & _).
  unfold Cc_1RB1RD_0LC0LC_0RD1LB_1LC1RA, cden, B0_1RB1RD_0LC0LC_0RD1LB_1LC1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RD_0LC0LC_0RD1LB_1LC1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (ILCounter.cview_none_I p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RD_0LC0LC_0RD1LB_1LC1RA
             = (StD, (rep [S1;S0] (S j) ++ [S1;S0], S0, ([]) ++ [S0]))).
  { unfold cden, B1_1RB1RD_0LC0LC_0RD1LB_1LC1RA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, (rep [S1;S0] (S j) ++ [S1;S0], S0, []))).
  { unfold Cc_1RB1RD_0LC0LC_0RD1LB_1LC1RA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. reflexivity.
Qed.

Lemma gsn_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_1RB1RD_0LC0LC_0RD1LB_1LC1RA.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_1RB1RD_0LC0LC_0RD1LB_1LC1RA, cden, AI0_1RB1RD_0LC0LC_0RD1LB_1LC1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_1RB1RD_0LC0LC_0RD1LB_1LC1RA) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_1RB1RD_0LC0LC_0RD1LB_1LC1RA, cden, AI1_1RB1RD_0LC0LC_0RD1LB_1LC1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 8), (cden (Ip q0 ++ [S1]) [] i AI1_1RB1RD_0LC0LC_0RD1LB_1LC1RA).
  split; [lia|]. split; [| exact (gen_1RB1RD_0LC0LC_0RD1LB_1LC1RA v i q0 E)].
  rewrite (gsn_1RB1RD_0LC0LC_0RD1LB_1LC1RA v i q0 E).
  exact (srun_sound tm false true chn_1RB1RD_0LC0LC_0RD1LB_1LC1RA AI0_1RB1RD_0LC0LC_0RD1LB_1LC1RA AI1_1RB1RD_0LC0LC_0RD1LB_1LC1RA 4 8
           run_inner_1RB1RD_0LC0LC_0RD1LB_1LC1RA (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall j, lift (cden [] [] j BB1_1RB1RD_0LC0LC_0RD1LB_1LC1RA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1RD_0LC0LC_0RD1LB_1LC1RA = (StD, (rep [S1;S0] j ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB1RD_0LC0LC_0RD1LB_1LC1RA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StD, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_1RB1RD_0LC0LC_0RD1LB_1LC1RA. rewrite epow2_1RB1RD_0LC0LC_0RD1LB_1LC1RA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1RD_0LC0LC_0RD1LB_1LC1RA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB1RD_0LC0LC_0RD1LB_1LC1RA.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1RD_0LC0LC_0RD1LB_1LC1RA, cden, BE0_1RB1RD_0LC0LC_0RD1LB_1LC1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB1RD_0LC0LC_0RD1LB_1LC1RA. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1RD_0LC0LC_0RD1LB_1LC1RA p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB1RD_0LC0LC_0RD1LB_1LC1RA).
    split; [lia|]. split; [| exact (gbo_1RB1RD_0LC0LC_0RD1LB_1LC1RA j)].
    rewrite (gso_1RB1RD_0LC0LC_0RD1LB_1LC1RA p j E).
    exact (srun_sound tm true true chb_1RB1RD_0LC0LC_0RD1LB_1LC1RA B0_1RB1RD_0LC0LC_0RD1LB_1LC1RA BB1_1RB1RD_0LC0LC_0RD1LB_1LC1RA 4 8
             run_boot_1RB1RD_0LC0LC_0RD1LB_1LC1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 12), (cden [] [] j B1_1RB1RD_0LC0LC_0RD1LB_1LC1RA).
    split; [| exact (geo_1RB1RD_0LC0LC_0RD1LB_1LC1RA p j E)].
    rewrite (gxi_1RB1RD_0LC0LC_0RD1LB_1LC1RA j).
    exact (srun_sound tm true true che_1RB1RD_0LC0LC_0RD1LB_1LC1RA BE0_1RB1RD_0LC0LC_0RD1LB_1LC1RA B1_1RB1RD_0LC0LC_0RD1LB_1LC1RA 4 12
             run_exit_1RB1RD_0LC0LC_0RD1LB_1LC1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RD_0LC0LC_0RD1LB_1LC1RA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1RD_0LC0LC_0RD1LB_1LC1RA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1RD_0LC0LC_0RD1LB_1LC1RA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 5.
  assert (H : match csteps tm 5 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 5 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RD_0LC0LC_0RD1LB_1LC1RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RD_0LC0LC_0RD1LB_1LC1RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RD_0LC0LC_0RD1LB_1LC1RA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1RD_0LC0LC_0RD1LB_1LC1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1RD_0LC0LC_0RD1LB_1LC1RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1RD_0LC0LC_0RD1LB_1LC1RA t p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB1RD_0LC0LC_0RD1LB_1LC1RA). split;
      [| exact (gbo_1RB1RD_0LC0LC_0RD1LB_1LC1RA j)].
    rewrite (gso_1RB1RD_0LC0LC_0RD1LB_1LC1RA p j E).
