  apply (fire_of_run_instr tm Cc true true l B0_1RB1RD_0LC0RA_1RA1LC_0LC1RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RD_0LC0RA_1RA1LC_0LC1RB p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RD_0LC0RA_1RA1LC_0LC1RB : forall t, ~ In t pins_1RB1RD_0LC0RA_1RA1LC_0LC1RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
