(** ** The lap *)

Lemma lap_1RB1RD_0LC0RB_0RA0LD_1RA1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
