  - destruct (lapi_1RB1RD_0LC0RB_0RA0LD_1RA1LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RD_0LC0RB_0RA0LD_1RA1LC B0_1RB1RD_0LC0RB_0RA0LD_1RA1LC B1_1RB1RD_0LC0RB_0RA0LD_1RA1LC 10 17 p j' [] []).
    + exact run_ovf_1RB1RD_0LC0RB_0RA0LD_1RA1LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RD_0LC0RB_0RA0LD_1RA1LC p j' E).
    + exact (geo_1RB1RD_0LC0RB_0RA0LD_1RA1LC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1RD_0LC0RB_0RA0LD_1RA1LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 5.
  assert (H : match csteps tm 5 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 5 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

