(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RD_0LC0RB_1LA1LD_1LC1LD : forall t, ~ In t pins_1RB1RD_0LC0RB_1LA1LD_1LC1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1RD_0LC0RB_1LA1LD_1LC1LD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1RD_0LC0RB_1LA1LD_1LC1LD
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RD_0LC0RB_1LA1LD_1LC1LD (StA, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1RD_0LC0RB_1LA1LD_1LC1LD [SRotL 1; SWin 1; SCycL 5 0; SWin 1] (StA, S1) ltac:(vm_compute; reflexivity)
