  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1RD_0LC0RB_1LA1LD_1LC1LD
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1RD_0LC0RB_1LA1LD_1LC1LD
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1RD_0LC0RB_1LA1LD_1LC1LD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RD_0LC0RB_1LA1LD_1LC1LD (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1RD_0LC0RB_1LA1LD_1LC1LD [SRotL 1; SWin 1; SCycL 5 0; SWin 5] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
