    intros p1 j1 E1.
    exact (firex_1RB1RD_0LC0RB_1LA1LD_1LC1LD [SRotL 1; SWin 1; SCycL 5 0; SWin 4] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RD_0LC0RB_1LA1LD_1LC1LD (StD, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1RD_0LC0RB_1LA1LD_1LC1LD [SRotL 1; SWin 1; SCycL 5 0; SWin 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB1RD_0LC0RB_1LA1LD_1LC1LD : NeverQuasiHaltsTr tm_1RB1RD_0LC0RB_1LA1LD_1LC1LD.
