    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_1RB1RD_0LC0RC_0RD1LB_1LC1RA. rewrite epow2_1RB1RD_0LC0RC_0RD1LB_1LC1RA.
    first [ rewrite <- app_assoc; reflexivity
