Lemma geo_1RB1RD_0LC1RA_1RB1LC_0LD0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RD_0LC1RA_1RB1LC_0LD0RB) = lift (Cc (Pos.succ p)).
