Lemma lapi_1RB1RD_0RC0LD_1LD0RB_1LA0RC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (12 * j + 10). split; [lia|].
  rewrite (gsi_1RB1RD_0RC0LD_1LD0RB_1LA0RC p j q0 E).
