(** Its mirror 1LB1LD_1RB0RC_0LA1RC_1LA0RC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1RD_1LB0LC_0RA1LC_1RA0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DL StD
  | StB, S0 => mk S1 DR StB | StB, S1 => mk S0 DR StC
  | StC, S0 => mk S0 DL StA | StC, S1 => mk S1 DR StC
  | StD, S0 => mk S1 DL StA | StD, S1 => mk S0 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1RD_1LB0LC_0RA1LC_1RA0LC : list Instr := [].
Definition tmw_1RB1RD_1LB0LC_0RA1LC_1RA0LC : TM := tm_wrap_trs tmm_1RB1RD_1LB0LC_0RA1LC_1RA0LC pins_1RB1RD_1LB0LC_0RA1LC_1RA0LC.
Local Notation tm := tmw_1RB1RD_1LB0LC_0RA1LC_1RA0LC.

Lemma mirror_ok_1RB1RD_1LB0LC_0RA1LC_1RA0LC : mirror_tm tm_1RB1RD_1LB0LC_0RA1LC_1RA0LC = tmm_1RB1RD_1LB0LC_0RA1LC_1RA0LC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB1RD_1LB0LC_0RA1LC_1RA0LC (p : positive) : cconf := (StC, (Jp p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB1RD_1LB0LC_0RA1LC_1RA0LC.

(** ** The certificate *)

Definition A0_1RB1RD_1LB0LC_0RA1LC_1RA0LC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition A1_1RB1RD_1LB0LC_0RA1LC_1RA0LC : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition chi_1RB1RD_1LB0LC_0RA1LC_1RA0LC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_int_1RB1RD_1LB0LC_0RA1LC_1RA0LC : srun tm false true chi_1RB1RD_1LB0LC_0RA1LC_1RA0LC A0_1RB1RD_1LB0LC_0RA1LC_1RA0LC = Some (A1_1RB1RD_1LB0LC_0RA1LC_1RA0LC, 4, 4).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1RD_1LB0LC_0RA1LC_1RA0LC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1RD_1LB0LC_0RA1LC_1RA0LC : sconf := mkC StC (mkS [] [S1;S1] 1 1 [S1;S0]) S0 (mkS [] [] 0 0 []).
(** ** The FIRST INNER anchor family -- Jp at StC *)
Definition Cin_1RB1RD_1LB0LC_0RA1LC_1RA0LC (v : positive) : cconf := (StC, (Jp v ++ [S1;S0;S1], S0, [])).
Local Notation Cin := Cin_1RB1RD_1LB0LC_0RA1LC_1RA0LC.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1RD_1LB0LC_0RA1LC_1RA0LC : forall n, Jp (pow2 n) = rep [S1;S1] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1RD_1LB0LC_0RA1LC_1RA0LC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB1RD_1LB0LC_0RA1LC_1RA0LC : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition chn_1RB1RD_1LB0LC_0RA1LC_1RA0LC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_inner_1RB1RD_1LB0LC_0RA1LC_1RA0LC : srun tm false true chn_1RB1RD_1LB0LC_0RA1LC_1RA0LC AI0_1RB1RD_1LB0LC_0RA1LC_1RA0LC = Some (AI1_1RB1RD_1LB0LC_0RA1LC_1RA0LC, 4, 4).
Proof. vm_compute. reflexivity. Qed.

(** ** The SECOND INNER anchor family -- Jp at StC *)
Definition Cin2_1RB1RD_1LB0LC_0RA1LC_1RA0LC (v : positive) : cconf := (StC, (Jp v ++ [S0;S0;S1], S0, [])).
Local Notation Cin2 := Cin2_1RB1RD_1LB0LC_0RA1LC_1RA0LC.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow22_1RB1RD_1LB0LC_0RA1LC_1RA0LC : forall n, Jp (pow2 n) = rep [S1;S1] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI20_1RB1RD_1LB0LC_0RA1LC_1RA0LC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition AI21_1RB1RD_1LB0LC_0RA1LC_1RA0LC : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition chn2_1RB1RD_1LB0LC_0RA1LC_1RA0LC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_inner2_1RB1RD_1LB0LC_0RA1LC_1RA0LC : srun tm false true chn2_1RB1RD_1LB0LC_0RA1LC_1RA0LC AI20_1RB1RD_1LB0LC_0RA1LC_1RA0LC = Some (AI21_1RB1RD_1LB0LC_0RA1LC_1RA0LC, 4, 4).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1RD_1LB0LC_0RA1LC_1RA0LC : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_1RB1RD_1LB0LC_0RA1LC_1RA0LC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 5; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_boot_1RB1RD_1LB0LC_0RA1LC_1RA0LC : srun tm true true chb_1RB1RD_1LB0LC_0RA1LC_1RA0LC B0_1RB1RD_1LB0LC_0RA1LC_1RA0LC = Some (BB1_1RB1RD_1LB0LC_0RA1LC_1RA0LC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** shift: count 1's all-ones fill -> count 2's anchor.
    WAVE18 section 4c -- "count 8->15, shift, count 8->15 again". *)
Definition BM0_1RB1RD_1LB0LC_0RA1LC_1RA0LC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition BM1_1RB1RD_1LB0LC_0RA1LC_1RA0LC : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition chm_1RB1RD_1LB0LC_0RA1LC_1RA0LC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_shift_1RB1RD_1LB0LC_0RA1LC_1RA0LC : srun tm true true chm_1RB1RD_1LB0LC_0RA1LC_1RA0LC BM0_1RB1RD_1LB0LC_0RA1LC_1RA0LC = Some (BM1_1RB1RD_1LB0LC_0RA1LC_1RA0LC, 4, 4).
