(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1RD_1LB0LC_0RA1LC_1RA0LC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S0;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1RD_1LB0LC_0RA1LC_1RA0LC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 6; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_exit_1RB1RD_1LB0LC_0RA1LC_1RA0LC : srun tm true true che_1RB1RD_1LB0LC_0RA1LC_1RA0LC BE0_1RB1RD_1LB0LC_0RA1LC_1RA0LC = Some (B1_1RB1RD_1LB0LC_0RA1LC_1RA0LC, 4, 8).
