  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB1RD_1LB0LC_0RA1LC_1RA0LC : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 4), (cden (Jp q0 ++ [S1;S0;S1]) [] i AI1_1RB1RD_1LB0LC_0RA1LC_1RA0LC).
  split; [lia|]. split; [| exact (gen_1RB1RD_1LB0LC_0RA1LC_1RA0LC v i q0 E)].
  rewrite (gsn_1RB1RD_1LB0LC_0RA1LC_1RA0LC v i q0 E).
  exact (srun_sound tm false true chn_1RB1RD_1LB0LC_0RA1LC_1RA0LC AI0_1RB1RD_1LB0LC_0RA1LC_1RA0LC AI1_1RB1RD_1LB0LC_0RA1LC_1RA0LC 4 4
           run_inner_1RB1RD_1LB0LC_0RA1LC_1RA0LC (Jp q0 ++ [S1;S0;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_1RB1RD_1LB0LC_0RA1LC_1RA0LC : forall j, lift (cden [] [] j BB1_1RB1RD_1LB0LC_0RA1LC_1RA0LC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1RD_1LB0LC_0RA1LC_1RA0LC = (StC, (rep [S1;S1] j ++ [S1;S1;S0;S1], S0, []))).
  { unfold cden, BB1_1RB1RD_1LB0LC_0RA1LC_1RA0LC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S1;S1] j ++ [S1;S1;S0;S1], S0, []))).
  { unfold Cin_1RB1RD_1LB0LC_0RA1LC_1RA0LC. rewrite epow2_1RB1RD_1LB0LC_0RA1LC_1RA0LC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1RD_1LB0LC_0RA1LC_1RA0LC. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1RD_1LB0LC_0RA1LC_1RA0LC : forall j, Cin (fill (pow2 j)) = cden [] [] j BM0_1RB1RD_1LB0LC_0RA1LC_1RA0LC.
Proof.
  intro j.
  destruct (JpCounter.cview_none_J (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1RD_1LB0LC_0RA1LC_1RA0LC, cden, BM0_1RB1RD_1LB0LC_0RA1LC_1RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

