(** ** Bootstrap *)

Lemma boot_1RB1RD_1LB0LC_0RA1LC_1RA0LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 7.
  assert (H : match csteps tm 7 c0 with
