(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1RD_1LB0LC_0RD1LC_1RA0LC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin2 lapin2_1RB1RD_1LB0LC_0RD1LC_1RA0LC p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (4 * j + 12), (cden [] [] j BB1_1RB1RD_1LB0LC_0RD1LC_1RA0LC).
      split; [lia|]. split; [| exact (gbo_1RB1RD_1LB0LC_0RD1LC_1RA0LC j)].
      rewrite (gso_1RB1RD_1LB0LC_0RD1LC_1RA0LC p j E).
      exact (srun_sound tm true true chb_1RB1RD_1LB0LC_0RD1LC_1RA0LC B0_1RB1RD_1LB0LC_0RD1LC_1RA0LC BB1_1RB1RD_1LB0LC_0RD1LC_1RA0LC 4 12
               run_boot_1RB1RD_1LB0LC_0RD1LC_1RA0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1RD_1LB0LC_0RD1LC_1RA0LC p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (4 * j + 8), (cden [] [] j BM1_1RB1RD_1LB0LC_0RD1LC_1RA0LC).
      split; [| exact (gbo2_1RB1RD_1LB0LC_0RD1LC_1RA0LC j)].
      rewrite (gxi_1RB1RD_1LB0LC_0RD1LC_1RA0LC j).
      exact (srun_sound tm true true chm_1RB1RD_1LB0LC_0RD1LC_1RA0LC BM0_1RB1RD_1LB0LC_0RD1LC_1RA0LC BM1_1RB1RD_1LB0LC_0RD1LC_1RA0LC 4 8
               run_shift_1RB1RD_1LB0LC_0RD1LC_1RA0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB2.
  - exists (4 * j + 12), (cden [] [] j B1_1RB1RD_1LB0LC_0RD1LC_1RA0LC).
    split; [| exact (geo_1RB1RD_1LB0LC_0RD1LC_1RA0LC p j E)].
    rewrite (gxi2_1RB1RD_1LB0LC_0RD1LC_1RA0LC j).
    exact (srun_sound tm true true che_1RB1RD_1LB0LC_0RD1LC_1RA0LC BE0_1RB1RD_1LB0LC_0RD1LC_1RA0LC B1_1RB1RD_1LB0LC_0RD1LC_1RA0LC 4 12
             run_exit_1RB1RD_1LB0LC_0RD1LC_1RA0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1RD_1LB0LC_0RD1LC_1RA0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RD_1LB0LC_0RD1LC_1RA0LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1RD_1LB0LC_0RD1LC_1RA0LC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1RD_1LB0LC_0RD1LC_1RA0LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 4.
  assert (H : match csteps tm 4 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 4 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RD_1LB0LC_0RD1LC_1RA0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RD_1LB0LC_0RD1LC_1RA0LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RD_1LB0LC_0RD1LC_1RA0LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RD_1LB0LC_0RD1LC_1RA0LC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RD_1LB0LC_0RD1LC_1RA0LC : forall t, ~ In t pins_1RB1RD_1LB0LC_0RD1LC_1RA0LC ->
