Definition tm_1RB1RD_1LB1LC_0RD0LC_1RA1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DR StD
  | StB, S0 => mk S1 DL StB | StB, S1 => mk S1 DL StC
  | StC, S0 => mk S0 DR StD | StC, S1 => mk S0 DL StC
  | StD, S0 => mk S1 DR StA | StD, S1 => mk S1 DR StA end.

(** Its mirror 1LB1LD_1RB1RC_0LD0RC_1LA1LA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1RD_1LB1LC_0RD0LC_1RA1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DL StD
  | StB, S0 => mk S1 DR StB | StB, S1 => mk S1 DR StC
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S0 DR StC
  | StD, S0 => mk S1 DL StA | StD, S1 => mk S1 DL StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1RD_1LB1LC_0RD0LC_1RA1RA : list Instr := [].
Definition tmw_1RB1RD_1LB1LC_0RD0LC_1RA1RA : TM := tm_wrap_trs tmm_1RB1RD_1LB1LC_0RD0LC_1RA1RA pins_1RB1RD_1LB1LC_0RD0LC_1RA1RA.
Local Notation tm := tmw_1RB1RD_1LB1LC_0RD0LC_1RA1RA.

Lemma mirror_ok_1RB1RD_1LB1LC_0RD0LC_1RA1RA : mirror_tm tm_1RB1RD_1LB1LC_0RD0LC_1RA1RA = tmm_1RB1RD_1LB1LC_0RD0LC_1RA1RA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB1RD_1LB1LC_0RD0LC_1RA1RA (p : positive) : cconf := (StD, (Dp p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB1RD_1LB1LC_0RD0LC_1RA1RA.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_1RB1RD_1LB1LC_0RD0LC_1RA1RA : sconf := mkC StD (mkS [S0;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_1RB1RD_1LB1LC_0RD0LC_1RA1RA : sconf := mkC StD (mkS [S1;S1] [] 0 0 []) S0 (mkS [S0] [] 0 0 []).
Definition chz_1RB1RD_1LB1LC_0RD0LC_1RA1RA : list lstep := [SWin 4; SWinR 2].

Lemma run_z_1RB1RD_1LB1LC_0RD0LC_1RA1RA : srun tm false true chz_1RB1RD_1LB1LC_0RD0LC_1RA1RA Z0_1RB1RD_1LB1LC_0RD0LC_1RA1RA = Some (Z1_1RB1RD_1LB1LC_0RD0LC_1RA1RA, 0, 6).
