Definition P0_1RB1RD_1LB1LC_0RD0LC_1RA1RA : sconf := mkC StD (mkS [S1;S1] [S1;S1] 1 0 [S0;S0]) S0 (mkS [] [] 0 0 []).
Definition P1_1RB1RD_1LB1LC_0RD0LC_1RA1RA : sconf := mkC StD (mkS [S0;S0] [S0;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chp_1RB1RD_1LB1LC_0RD0LC_1RA1RA : list lstep := [SWin 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2; SWinR 2].

Lemma run_p_1RB1RD_1LB1LC_0RD0LC_1RA1RA : srun tm false true chp_1RB1RD_1LB1LC_0RD0LC_1RA1RA P0_1RB1RD_1LB1LC_0RD0LC_1RA1RA = Some (P1_1RB1RD_1LB1LC_0RD0LC_1RA1RA, 4, 10).
