Definition B0_1RB1RD_1LB1LC_0RD0LC_1RA1RA : sconf := mkC StD (mkS [S1;S1] [S1;S1] 1 0 [S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1RD_1LB1LC_0RD0LC_1RA1RA : sconf := mkC StD (mkS [] [S0;S0] 1 1 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition cho_1RB1RD_1LB1LC_0RD0LC_1RA1RA : list lstep := [SWin 2; SCycL 2 0; SWin 1; SWinL 3; SCycR 2; SWin 2; SWinR 2; SFoldL 1].

Lemma run_ovf_1RB1RD_1LB1LC_0RD0LC_1RA1RA : srun tm true true cho_1RB1RD_1LB1LC_0RD0LC_1RA1RA B0_1RB1RD_1LB1LC_0RD0LC_1RA1RA = Some (B1_1RB1RD_1LB1LC_0RD0LC_1RA1RA, 4, 10).
