(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1RD_1LB1LC_0RD0LC_1RA1RA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Dp q0 ++ [S0]) [] 0 Z0_1RB1RD_1LB1LC_0RD0LC_1RA1RA /\
  lift (cden (Dp q0 ++ [S0]) [] 0 Z1_1RB1RD_1LB1LC_0RD0LC_1RA1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p q0 E. destruct (DpCounter.cview_some_D p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1RD_1LB1LC_0RD0LC_1RA1RA, cden, Z0_1RB1RD_1LB1LC_0RD0LC_1RA1RA, Z1_1RB1RD_1LB1LC_0RD0LC_1RA1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1RD_1LB1LC_0RD0LC_1RA1RA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Dp q0 ++ [S0]) [] j P0_1RB1RD_1LB1LC_0RD0LC_1RA1RA /\
  lift (cden (Dp q0 ++ [S0]) [] j P1_1RB1RD_1LB1LC_0RD0LC_1RA1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (DpCounter.cview_some_D p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1RD_1LB1LC_0RD0LC_1RA1RA, cden, P0_1RB1RD_1LB1LC_0RD0LC_1RA1RA, P1_1RB1RD_1LB1LC_0RD0LC_1RA1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RD_1LB1LC_0RD0LC_1RA1RA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1RD_1LB1LC_0RD0LC_1RA1RA p q0 E) as (HA & HB).
    exists (0 * 0 + 6), (cden (Dp q0 ++ [S0]) [] 0 Z1_1RB1RD_1LB1LC_0RD0LC_1RA1RA).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_1RB1RD_1LB1LC_0RD0LC_1RA1RA Z0_1RB1RD_1LB1LC_0RD0LC_1RA1RA Z1_1RB1RD_1LB1LC_0RD0LC_1RA1RA 0 6
             run_z_1RB1RD_1LB1LC_0RD0LC_1RA1RA (Dp q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - destruct (gp_1RB1RD_1LB1LC_0RD0LC_1RA1RA p j' q0 E) as (HA & HB).
    exists (4 * j' + 10), (cden (Dp q0 ++ [S0]) [] j' P1_1RB1RD_1LB1LC_0RD0LC_1RA1RA).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chp_1RB1RD_1LB1LC_0RD0LC_1RA1RA P0_1RB1RD_1LB1LC_0RD0LC_1RA1RA P1_1RB1RD_1LB1LC_0RD0LC_1RA1RA 4 10
             run_p_1RB1RD_1LB1LC_0RD0LC_1RA1RA (Dp q0 ++ [S0]) [] j'
             ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB1RD_1LB1LC_0RD0LC_1RA1RA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RD_1LB1LC_0RD0LC_1RA1RA.
Proof.
  intros p j E. destruct (DpCounter.cview_none_D p j E) as (H1 & _).
  unfold Cc_1RB1RD_1LB1LC_0RD0LC_1RA1RA, cden, B0_1RB1RD_1LB1LC_0RD0LC_1RA1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1RD_1LB1LC_0RD0LC_1RA1RA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RD_1LB1LC_0RD0LC_1RA1RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RD_1LB1LC_0RD0LC_1RA1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (DpCounter.cview_none_D p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RD_1LB1LC_0RD0LC_1RA1RA
             = (StD, (rep [S0;S0] (S j) ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_1RB1RD_1LB1LC_0RD0LC_1RA1RA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S0;S0] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1RD_1LB1LC_0RD0LC_1RA1RA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_1RB1RD_1LB1LC_0RD0LC_1RA1RA. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB1RD_1LB1LC_0RD0LC_1RA1RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RD_1LB1LC_0RD0LC_1RA1RA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RD_1LB1LC_0RD0LC_1RA1RA B0_1RB1RD_1LB1LC_0RD0LC_1RA1RA B1_1RB1RD_1LB1LC_0RD0LC_1RA1RA 4 10 p j' [] []).
    + exact run_ovf_1RB1RD_1LB1LC_0RD0LC_1RA1RA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RD_1LB1LC_0RD0LC_1RA1RA p j' E).
    + exact (geo_1RB1RD_1LB1LC_0RD0LC_1RA1RA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1RD_1LB1LC_0RD0LC_1RA1RA : exists t0, stepn tm t0 InitES = Some (lift (Cc 2)).
Proof.
  exists 14.
  assert (H : match csteps tm 14 c0 with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 14 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RD_1LB1LC_0RD0LC_1RA1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RD_1LB1LC_0RD0LC_1RA1RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RD_1LB1LC_0RD0LC_1RA1RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RD_1LB1LC_0RD0LC_1RA1RA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RD_1LB1LC_0RD0LC_1RA1RA : forall t, ~ In t pins_1RB1RD_1LB1LC_0RD0LC_1RA1RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1RD_1LB1LC_0RD0LC_1RA1RA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_1LB1LC_0RD0LC_1RA1RA [SWin 2; SCycL 2 0; SWin 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_1LB1LC_0RD0LC_1RA1RA [SWin 1] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_1LB1LC_0RD0LC_1RA1RA [SWin 2; SCycL 2 0; SWin 1; SWinL 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_1LB1LC_0RD0LC_1RA1RA [SWin 2; SCycL 2 0; SWin 1; SWinL 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_1LB1LC_0RD0LC_1RA1RA [SWin 2; SCycL 2 0; SWin 1; SWinL 3; SCycR 2; SWin 2; SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_1LB1LC_0RD0LC_1RA1RA [SWin 2; SCycL 2 0; SWin 1; SWinL 3] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_1LB1LC_0RD0LC_1RA1RA [] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_1LB1LC_0RD0LC_1RA1RA [SWin 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtrm_1RB1RD_1LB1LC_0RD0LC_1RA1RA : NeverQuasiHaltsTr tmm_1RB1RD_1LB1LC_0RD0LC_1RA1RA.
Proof.
  apply (glue_neverqhtr tmm_1RB1RD_1LB1LC_0RD0LC_1RA1RA pins_1RB1RD_1LB1LC_0RD0LC_1RA1RA Cc 2).
  - exact boot_1RB1RD_1LB1LC_0RD0LC_1RA1RA.
  - intros p _. apply lap_1RB1RD_1LB1LC_0RD0LC_1RA1RA.
  - intros t Ht p _. apply fire_1RB1RD_1LB1LC_0RD0LC_1RA1RA. exact Ht.
Qed.

Theorem nqhtr_1RB1RD_1LB1LC_0RD0LC_1RA1RA : NeverQuasiHaltsTr tm_1RB1RD_1LB1LC_0RD0LC_1RA1RA.
Proof. apply (neverqhtr_mirror tm_1RB1RD_1LB1LC_0RD0LC_1RA1RA). rewrite mirror_ok_1RB1RD_1LB1LC_0RD0LC_1RA1RA. exact nqhtrm_1RB1RD_1LB1LC_0RD0LC_1RA1RA. Qed.

Theorem nonhalt_1RB1RD_1LB1LC_0RD0LC_1RA1RA : NonHalt tm_1RB1RD_1LB1LC_0RD0LC_1RA1RA.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB1RD_1LB1LC_0RD0LC_1RA1RA. Qed.

