    intros p1 j1 E1.
    exact (firex_1RB1RD_1LB1RC_0RA1LC_1RA0LC [SRotL 1; SWin 1; SCycL 2 0; SWinL 3] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RD_1LB1RC_0RA1LC_1RA0LC (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1RD_1LB1RC_0RA1LC_1RA0LC [SRotL 1; SWin 1; SCycL 2 0; SWinL 4] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1RD_1LB1RC_0RA1LC_1RA0LC
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
