(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_1RB1RD_1LB1RC_0RD1LC_1RA0LC : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_1RB1RD_1LB1RC_0RD1LC_1RA0LC = Some q ->
