  apply (vis_via_fill tm Cc Cin lapin_1RB1RD_1LB1RC_0RD1LC_1RA0LC q p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB1RD_1LB1RC_0RD1LC_1RA0LC). split;
      [| exact (gbo_1RB1RD_1LB1RC_0RD1LC_1RA0LC j)].
    rewrite (gso_1RB1RD_1LB1RC_0RD1LC_1RA0LC p j E).
