(** ** The lap *)

Lemma lap_1RB1RD_1LB1RC_0RD1LC_1RA0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
