(** ** The lap *)

Lemma lap_1RB1RD_1LC0LB_1RA0LB_0RD0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
